def 计节点(值):
    if isinstance(值, list):
        总数 = 1
        for 元素 in 值:
            总数 += 计节点(元素)
        return 总数
    if isinstance(值, dict):
        总数 = 1
        for 键 in 值:
            总数 += 计节点(值[键])
        return 总数
    return 1

